/// ai-attachment-tray: Progress, error and retry
private struct AiAttachmentTrayExample0: View {
    private let initial = [
        MonarchAiAttachmentTrayFile(id: "brief", name: "Project brief.pdf", size: 2_450_000, contentType: "application/pdf"),
        MonarchAiAttachmentTrayFile(id: "data", name: "Survey results.csv", size: 384_000, contentType: "text/csv", progress: 0.1),
        MonarchAiAttachmentTrayFile(id: "deck", name: "Kickoff slides.pptx", size: 48_000_000, contentType: "application/vnd.openxmlformats-officedocument.presentationml.presentation", errorMessage: "Larger than the 25 MB limit"),
    ]
    @State private var files: [MonarchAiAttachmentTrayFile] = []

    var body: some View {
        VStack(spacing: MonarchTokens.Space.space2) {
            MonarchAiAttachmentTray(
                files,
                onRetry: { _ in },
                onRemove: { id in files.removeAll { $0.id == id } }
            )
            MonarchButton("Reset", variant: .ghost, size: .sm) { files = initial }
        }
        .onAppear { files = initial }
    }
}

/// ai-autofill-field: Fields filled from a document
private struct AiAutofillFieldExample0: View {
    @State private var value0 = "Northwind Ltd"
    @State private var state0: MonarchAiAutofillState = .suggested
    @State private var value1 = "1,240.00"
    @State private var state1: MonarchAiAutofillState = .suggested
    @State private var value2 = "2026-05-30"
    @State private var state2: MonarchAiAutofillState = .suggested

    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
            MonarchAiAutofillField(
                state: state0,
                suggestion: "Northwind Ltd",
                fieldName: "Company".lowercased(),
                source: "invoice-0412.pdf",
                confidence: 0.93,
                onAccept: { state0 = .accepted },
                onClear: {
                    value0 = ""
                    state0 = .cleared
                },
                control: { MonarchTextField("Company", text: $value0) }
            )
            MonarchAiAutofillField(
                state: state1,
                suggestion: "1,240.00",
                fieldName: "Invoice total".lowercased(),
                source: "invoice-0412.pdf",
                confidence: 0.71,
                onAccept: { state1 = .accepted },
                onClear: {
                    value1 = ""
                    state1 = .cleared
                },
                control: { MonarchTextField("Invoice total", text: $value1) }
            )
            MonarchAiAutofillField(
                state: state2,
                suggestion: "2026-05-30",
                fieldName: "Due date".lowercased(),
                confidence: 0.38,
                onAccept: { state2 = .accepted },
                onClear: {
                    value2 = ""
                    state2 = .cleared
                },
                control: { MonarchTextField("Due date", text: $value2) }
            )
        }
        .frame(maxWidth: 416)
    }
}

