/// ai-citation: Inline citations with a preview
private struct AiCitationExample0: View {
    @State private var previewed: MonarchAiSourcePart?
    private static func words(_ text: String) -> [String] { text.split(separator: " ").map(String.init) }
    private let handbook = MonarchAiSourcePart(id: "s1", title: "Team handbook", url: "https://example.com/handbook", kind: .doc, product: "Docs")
    private let policy = MonarchAiSourcePart(id: "s2", title: "Support policy", url: "https://example.com/support-policy", kind: .web)

    var body: some View {
        MonarchFlowLayout(spacing: 0, rowSpacing: 4, alignment: .firstTextBaseline) {
            ForEach(Array(Self.words("Requests are answered within two working days").dropLast().enumerated()), id: \.offset) { _, word in
                Text("\(word) ").monarchTextStyle(.body)
            }
            HStack(alignment: .firstTextBaseline, spacing: 0) {
                Text(Self.words("Requests are answered within two working days").last ?? "").monarchTextStyle(.body)
                MonarchAiCitation(1, source: handbook, quote: "Requests are answered within two working days.", onOpen: { previewed = $0 })
                Text(Self.words(", and urgent issues have a separate queue").first.map { $0 + " " } ?? "").monarchTextStyle(.body)
            }
            ForEach(Array(Self.words(", and urgent issues have a separate queue").dropFirst().dropLast().enumerated()), id: \.offset) { _, word in
                Text("\(word) ").monarchTextStyle(.body)
            }
            HStack(alignment: .firstTextBaseline, spacing: 0) {
                Text(Self.words(", and urgent issues have a separate queue").last ?? "").monarchTextStyle(.body)
                MonarchAiCitation(2, source: policy)
                Text(".").monarchTextStyle(.body)
            }
        }
        .sheet(item: $previewed) { source in
            MonarchAiSourcePreview(source, quote: "Requests are answered within two working days.", content: "Welcome to the team.\n\nRequests are answered within two working days. Urgent issues go to the on-call queue.\n\nSee the support policy for details.")
        }
    }
}

