/// ai-conversation: Stop, try again and switch between versions
private struct AiConversationExample1: View {
    private struct EchoTransport: MonarchAiTransport {
        func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
            MonarchAiEventStream { continuation in
                continuation.yield(.textDelta("You asked: "))
                continuation.yield(.textDelta(request.messages.last?.text ?? ""))
                continuation.yield(.done())
                continuation.finish()
            }
        }
    }

    @State private var conversation = MonarchAiConversation(transport: EchoTransport())

    var body: some View {
        VStack(alignment: .leading) {
            if let reply = conversation.messages.last, reply.role == .assistant {
                Text(reply.text).monarchTextStyle(.body)
                if let branch = reply.branch {
                    MonarchAiMessageBranch(
                        selection: Binding(get: { branch.index }, set: { conversation.branchTo(reply.id, index: $0) }),
                        count: branch.count
                    )
                }
            }
            if let error = conversation.error {
                MonarchAiErrorMessage(MonarchAiErrorKind(code: error.code), onRetry: { conversation.retry() })
            }
            HStack {
                Button("Ask") { conversation.send("Hello") }
                Button("Stop") { conversation.stop() }.disabled(!conversation.isBusy)
                Button("Regenerate") { conversation.regenerate() }.disabled(conversation.isBusy)
            }
            .buttonStyle(.monarch(.secondary, size: .sm))
        }
    }
}

