/// ai-eval-review: Review queue with a submit footer
private struct AiEvalReviewExample0: View {
    struct EvalItem: Identifiable {
        let id: String
        let title: String
        let prompt: String
        let output: String
        var reference: String? = nil
        let meta: String
    }
    struct Criterion: Identifiable {
        let id: String
        let label: String
        var detail: String? = nil
        var scale = 5
    }
    @Environment(\.monarchTheme) private var theme
    private let items = [
        EvalItem(
            id: "q1",
            title: "Summarise a meeting",
            prompt: "Summarise the attached meeting notes in three bullet points.",
            output: "- The launch moves to **next Tuesday**.\n- Design owns the final copy review.\n- Support needs the FAQ by Friday.",
            reference: "Launch moved to Tuesday; design reviews copy; support needs the FAQ by Friday.",
            meta: "Model A · 12 Oct"
        ),
        EvalItem(
            id: "q2",
            title: "Answer a policy question",
            prompt: "Can I expense a train ticket for a client visit?",
            output: "Yes. Travel for client visits is reimbursable with a receipt, up to the standard fare.",
            meta: "Model A · 12 Oct"
        ),
        EvalItem(
            id: "q3",
            title: "Draft a reply",
            prompt: "Draft a short, polite reply declining the invitation.",
            output: "Thank you for the invitation. Unfortunately I can’t join this time, but I hope it goes well.",
            meta: "Model B · 13 Oct"
        ),
    ]
    private let rubric = [
        Criterion(id: "accuracy", label: "Accuracy", detail: "Facts match the source or reference."),
        Criterion(id: "completeness", label: "Completeness", detail: "Covers everything asked."),
        Criterion(id: "tone", label: "Tone", scale: 3),
    ]
    // Reviews by item id; persist every change in the app so no review is lost.
    @State private var scores: [String: [String: Int]] = [:]
    @State private var notes: [String: String] = [:]
    @State private var verdicts: [String: String] = [:]
    @State private var current: String? = "q1"

    private func score(_ item: String, _ criterion: String) -> Binding<Int?> {
        Binding(get: { scores[item]?[criterion] }, set: { scores[item, default: [:]][criterion] = $0 })
    }

    private func note(_ item: String) -> Binding<String> {
        Binding(get: { notes[item] ?? "" }, set: { notes[item] = $0 })
    }

    private func verdict(_ item: String) -> Binding<String?> {
        Binding(get: { verdicts[item] }, set: { verdicts[item] = $0 })
    }

    private func verdictText(_ item: String) -> String {
        switch verdicts[item] {
        case "pass": "Pass"
        case "fail": "Fail"
        default: "Not reviewed"
        }
    }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    VStack(alignment: .leading, spacing: theme.spacing.space2) {
                        ProgressView(
                            "\(verdicts.count) of \(items.count) reviewed",
                            value: Double(verdicts.count),
                            total: Double(items.count)
                        )
                        .progressViewStyle(.monarchLinear)
                        ForEach(items) { item in
                            Button { current = item.id } label: {
                                HStack {
                                    Text(item.title).monarchTextStyle(.body)
                                    Spacer()
                                    Text(verdictText(item.id))
                                        .monarchTextStyle(.caption)
                                        .foregroundStyle(theme.colors.textMuted)
                                }
                                .padding(theme.spacing.space2)
                                .background(
                                    current == item.id ? theme.colors.aiSubtle : Color.clear,
                                    in: RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous)
                                )
                                .contentShape(Rectangle())
                            }
                            .buttonStyle(.plain)
                            .accessibilityAddTraits(current == item.id ? .isSelected : [])
                        }
                    }
                    Divider()
                    if let index = items.firstIndex(where: { $0.id == current }) {
                        let item = items[index]
                        let total = rubric.compactMap { scores[item.id]?[$0.id] }.reduce(0, +)
                        let maximum = rubric.map(\.scale).reduce(0, +)
                        VStack(alignment: .leading, spacing: theme.spacing.space4) {
                        Text("\(index + 1) of \(items.count)")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                        Text(item.title).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                        Text(item.meta)
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                        HStack(spacing: theme.spacing.space2) {
                            MonarchButton("Previous", size: .sm) {
                                current = items[index - 1].id
                            }
                            .disabled(index == 0)
                            MonarchButton("Next", size: .sm) {
                                current = items[index + 1].id
                            }
                            .disabled(index == items.count - 1)
                        }
                        VStack(alignment: .leading, spacing: theme.spacing.space1) {
                            Text("PROMPT").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted).accessibilityAddTraits(.isHeader)
                            Text(item.prompt).monarchTextStyle(.body)
                        }
                        .padding(theme.spacing.space3)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .background(RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: 1))
                        VStack(alignment: .leading, spacing: theme.spacing.space1) {
                            HStack(spacing: theme.spacing.space2) {
                                Text("OUTPUT").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted).accessibilityAddTraits(.isHeader)
                                Spacer(minLength: 0)
                                MonarchAiGeneratedBadge(size: .sm)
                            }
                            MonarchAiMarkdown(item.output)
                        }
                        .padding(theme.spacing.space3)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .background(RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous).strokeBorder(theme.colors.aiBorder, lineWidth: 1))
                        if let reference = item.reference {
                            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                                Text("EXPECTED").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted).accessibilityAddTraits(.isHeader)
                                Text(reference).monarchTextStyle(.body)
                            }
                            .padding(theme.spacing.space3)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .background(RoundedRectangle(cornerRadius: MonarchTokens.Radius.md, style: .continuous).strokeBorder(theme.colors.borderSubtle, lineWidth: 1))
                        }
                        HStack {
                            Text("RUBRIC").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted).accessibilityAddTraits(.isHeader)
                            Spacer(minLength: 0)
                            Text("Score \(total) / \(maximum)").monarchTextStyle(.bodyStrong)
                        }
                        ForEach(rubric) { criterion in
                            MonarchRatingPicker(
                                criterion.label,
                                value: score(item.id, criterion.id),
                                in: 1...criterion.scale,
                                isClearable: true,
                                helper: criterion.detail
                            )
                        }
                        MonarchTextField("Notes", text: note(item.id), axis: .vertical, lineLimit: 3...8)
                        Text("Verdict").monarchTextStyle(.label).accessibilityAddTraits(.isHeader)
                        HStack(spacing: theme.spacing.space3) {
                            Toggle("Pass", systemImage: "checkmark", isOn: Binding(
                                get: { verdicts[item.id] == "pass" },
                                set: { verdicts[item.id] = $0 ? "pass" : nil }
                            ))
                            Toggle("Fail", systemImage: "xmark", isOn: Binding(
                                get: { verdicts[item.id] == "fail" },
                                set: { verdicts[item.id] = $0 ? "fail" : nil }
                            ))
                        }
                        .toggleStyle(.monarchButton(.outline, size: .md))
                        Text("J K P F  previous / next, pass / fail")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                        MonarchButton("Submit reviews", variant: .primary, fullWidth: true) {
                            // Send the reviews to the evaluation service.
                        }
                        .disabled(verdicts.count < items.count)

                        }
                    } else {
                        MonarchEmptyState("Nothing to review", message: "Outputs to review appear here.")
                    }
                }
                .padding(theme.spacing.space4)
            }
            .monarchCanvas()
            #if os(iOS)
            .toolbar(.hidden, for: .navigationBar)
            #endif
        }
    }
}

