/// ai-generative-ui: Allow-listed component
private struct AiGenerativeUiExample0: View {
    struct MetricProps: Decodable, Sendable {
        let label: String
        let value: String
        let change: String?
    }

    var registry: MonarchAiUiRegistry {
        var registry = MonarchAiUiRegistry()
        registry.register("MetricCard", props: MetricProps.self) { props, _ in
            MonarchCard {
                Text(props.label).monarchTextStyle(.subheading)
                Text(props.value).monarchTextStyle(.title)
                if let change = props.change {
                    MonarchBadge(change, tone: .success)
                }
            }
        }
        return registry
    }

    var body: some View {
        MonarchAiGenerativeUi(
            MonarchAiUiPart(component: "MetricCard", props: ["label": "Active projects", "value": "42", "change": "+6 this month"]),
            registry: registry
        )
    }
}

