/// ai-image-generation: Generate, refine and choose
private struct AiImageGenerationExample0: View {
    @Environment(\.colorScheme) private var scheme
    @State private var images: [MonarchAiGeneratedImage] = []
    @State private var chosen: String?

    /// The four pictures, drawn for the scheme: a pale grey in the light theme, a dark grey in the dark theme.
    private static func pictures(dark: Bool) -> [MonarchAiGeneratedImage] {
        [
            MonarchAiGeneratedImage(id: "a", image: placeholder(0, dark: dark), alt: "Abstract hills under a round sun"),
            MonarchAiGeneratedImage(id: "b", image: placeholder(1, dark: dark), alt: ""),
            MonarchAiGeneratedImage(id: "c", image: placeholder(2, dark: dark), alt: "Two overlapping shapes on a pale ground"),
            MonarchAiGeneratedImage(id: "d", image: placeholder(3, dark: dark), alt: ""),
        ]
    }

    /// A grey picture with a sun and a hill, so the grid shows what a generated image looks like.
    private static func placeholder(_ index: Int, dark: Bool) -> Image {
        let size = 240
        let context = CGContext(
            data: nil, width: size, height: size, bitsPerComponent: 8, bytesPerRow: 0,
            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
        context.setFillColor(gray: dark ? 0.14 : 0.88, alpha: 1)
        context.fill(CGRect(x: 0, y: 0, width: size, height: size))
        context.setFillColor(gray: dark ? 0.10 : 0.57, alpha: 1)
        let sunX: CGFloat = index == 3 ? 180 : 80
        context.fillEllipse(in: CGRect(x: sunX - 36, y: 150, width: 72, height: 72))
        context.setFillColor(gray: dark ? 0.07 : 0.44, alpha: 1)
        context.move(to: CGPoint(x: 0, y: 0))
        context.addLine(to: CGPoint(x: index == 3 ? 130 : 100, y: 130))
        context.addLine(to: CGPoint(x: size, y: 0))
        context.fillPath()
        return Image(decorative: context.makeImage()!, scale: 1)
    }


    var body: some View {
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
            MonarchButton("Generate again", variant: .secondary, size: .sm) {}
            MonarchAiImageGeneration(
                images: $images,
                status: .done,
                selection: $chosen,
                onVariations: { _ in }
            )
        }
        .onChange(of: scheme, initial: true) { images = Self.pictures(dark: scheme == .dark) }
    }
}

