/// ai-scroll-anchor: Scrolled up, with a jump button
private struct AiScrollAnchorExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var position: Int? = 10 - 4

    private let lines = [
        "The draft has three sections.",
        "The first summarises the request.",
        "The second lists the open questions.",
        "The third proposes next steps.",
        "Each step has an owner and a date.",
        "Nothing is sent until you approve it.",
    ]

    var body: some View {
        VStack {
            ScrollView {
                LazyVStack(alignment: .leading, spacing: theme.spacing.space2) {
                    ForEach(0..<10, id: \.self) { index in
                        Text(lines[index % lines.count])
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textDefault)
                            .id(index)
                    }
                }
                .scrollTargetLayout()
                .frame(maxWidth: .infinity, alignment: .leading)
            }
            .scrollPosition(id: $position, anchor: .bottom)
            .defaultScrollAnchor(.bottom)
            .frame(height: theme.spacing.space24 * 2)
            if position != 10 - 1 {
                MonarchButton("Jump to latest", size: .sm) {
                    withAnimation { position = 10 - 1 }
                }
            }
        }
        .padding(.horizontal)
    }
}

/// ai-scroll-anchor: Jump to latest
private struct AiScrollAnchorExample1: View {
    @Environment(\.monarchTheme) private var theme
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var position: Int?

    private let messages = Array(1...12)

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            ScrollView {
                LazyVStack(alignment: .leading, spacing: theme.spacing.space2) {
                    ForEach(messages, id: \.self) { message in
                        Text("Message \(message)")
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textDefault)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .scrollTargetLayout()
            }
            .defaultScrollAnchor(.bottom)
            .scrollPosition(id: $position, anchor: .bottom)
            .frame(height: theme.spacing.space24 * 2)

            Button("Jump to latest") {
                withAnimation(theme.motion.animation(reduceMotion: reduceMotion)) {
                    position = messages.last
                }
            }
            .buttonStyle(.monarch(.secondary, size: .sm))
        }
    }
}

